(window.JCPA_DATA=window.JCPA_DATA||{})["integrity"]={"id":"integrity","name":"قانون النزاهة ومكافحة الفساد","full":"قانون النزاهة ومكافحة الفساد رقم (13) لسنة 2016","icon":"🏛️","articles":[{"n":"1","chapter":"","source":"يسمى هذا القانون (قانون النزاهة ومكافحة الفساد لسنة 2016) ويعمل به بعد ثلاثين يوما من\nتاريخ نشره في الجريدة الرسمية.","notes":[],"title":"تسمية القانون ونفاذه","memo":"⭐ قانون النزاهة ومكافحة الفساد لسنة 2016\n⭐ يعمل به بعد ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"يعمل بقانون النزاهة ومكافحة الفساد لسنة 2016:","o":["بعد ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية","من تاريخ نشره في الجريدة الرسمية","بعد ستين يوماً من تاريخ نشره في الجريدة الرسمية","بعد تسعين يوماً من تاريخ نشره في الجريدة الرسمية"],"a":0}]},{"n":"2","chapter":"","source":"يكون للكلمات والعبارات التالية حيثما وردت فى هذا القانون المعاني المخصصة لها أدناه ما لم تدل\nالقرينة على غير ذلك:\nالهيئة: هيئة النزاهة ومكافحة الفساد المنشأة بمقتضى أحكام هذا القانون.\nالإدارة العامة: الوزارات والدوائر الحكومية والمؤسسات الرسمية العامة والمؤسسات العامة\nوالبلديات.","notes":[],"title":"التعريفات","memo":"⭐ الهيئة: هيئة النزاهة ومكافحة الفساد\n⭐ الإدارة العامة: الوزارات والدوائر الحكومية والمؤسسات الرسمية العامة والمؤسسات العامة والبلديات","qs":[{"q":"وفق تعريف (الإدارة العامة) في قانون النزاهة ومكافحة الفساد، أي مما يلي يدخل ضمنها؟","o":["البلديات","الشركات المساهمة العامة","الجمعيات","مؤسسات المجتمع المدني"],"a":0},{"q":"أي مما يلي لا يدخل ضمن تعريف (الإدارة العامة) وفق قانون النزاهة ومكافحة الفساد؟","o":["الشركات غير الربحية","الوزارات","المؤسسات الرسمية العامة","الدوائر الحكومية"],"a":0}]},{"n":"3","chapter":"","source":"أ. تنشأ في المملكة هيئة تسمى (هيئة النزاهة ومكافحة الفساد) تتمتع بشخصية اعتبارية وباستقلال\nمالي وإداري ولها بهذه الصفة القيام بجميع التصرفات القانونية اللازمة لتحقيق أهدافها بما في\nذلك إبرام العقود وتملك الأموال المنقولة وغير المنقولة ولها حق التقاضي وينوب عنها في\nالإجراءات القضائية الوكيل العام.2\nب. يكون المقر الرئيس للهيئة في عمان.3","notes":[],"title":"إنشاء الهيئة وشخصيتها الاعتبارية","memo":"⭐ تتمتع الهيئة بشخصية اعتبارية واستقلال مالي وإداري\n⭐ ينوب عنها في الإجراءات القضائية الوكيل العام\n⭐ المقر الرئيس للهيئة في عمان","qs":[{"q":"ينوب عن هيئة النزاهة ومكافحة الفساد في الإجراءات القضائية:","o":["الوكيل العام","المدعي العام المختص","رئيس الهيئة","النائب العام"],"a":0},{"q":"يكون المقر الرئيس لهيئة النزاهة ومكافحة الفساد في:","o":["عمان","العقبة","إربد","الزرقاء"],"a":0},{"q":"تتمتع هيئة النزاهة ومكافحة الفساد بـ:","o":["شخصية اعتبارية وباستقلال مالي وإداري","استقلال إداري فقط وتتبع مالياً لوزارة المالية","استقلال مالي فقط وتتبع إدارياً لرئاسة الوزراء","شخصية اعتبارية وتتبع مالياً وإدارياً لمجلس الوزراء"],"a":0}]},{"n":"4","chapter":"","source":"تهدف الهيئة إلى ضمان الالتزام بمبادئ النزاهة الوطنية ومكافحة الفساد من خلال:\nأ. تفعيل منظومة القيم والقواعد السلوكية في الإدارة العامة وضمان تكاملها.\nب. التأكد من ان الإدارة العامة تقدم الخدمة للمواطن بجودة عالية وبشفافية وعدالة.\nج. التأكد من التزام الإدارة العامة بمبادئ الحوكمة الرشيدة ومعايير المساواة والجدارة والاستحقاق وتكافؤ الفرص.\nد. التأكد من التزام السلطة التنفيذية بالشفافية عند وضع السياسات واتخاذ القرارات وضمان حق المواطن في الاطلاع على المعلومات وفقاً للتشريعات.\nهـ. التأكد من تطبيق الإدارة العامة للتشريعات بشفافية وبما يحقق مبادئ العدالة والمساواة وتكافؤ الفرص.\nو. التأكد من وجود إطار قانوني ينظم مساءلة المسؤولين ومتخذي القرار في الإدارة العامة ومحاسبتهم.\nز. تلقي شكاوى المتضررين وتظلماتهم وفقاً لأحكام هذا القانون.\nح. التعاون في تقديم وطلب المساعدة القانونية الدولية في مجال مكافحة الفساد حال توافر شروط تقديمها من خلال القنوات الرسمية.\nط. التحري عن الفساد المالي والإداري بكل أشكاله والكشف عن المخالفات والتجاوزات وجمع الأدلة والمعلومات الخاصة بذلك ومباشرة التحقيقات والسير في الإجراءات الإدارية والقانونية اللازمة لذلك.\nي. ملاحقة كل من يرتكب أياً من أفعال الفساد واتخاذ الإجراءات اللازمة لذلك.\nك. مكافحة اغتيال الشخصية.\nل. التأكد من قيام مؤسسات الرقابة على القطاع الخاص ومؤسسات المجتمع المدني بوضع معايير الحوكمة الرشيدة وسلامة تطبيقها.","notes":[],"title":"أهداف الهيئة","memo":"⭐ ضمان الالتزام بمبادئ النزاهة الوطنية ومكافحة الفساد\n⭐ من أهدافها: تلقي شكاوى المتضررين وتظلماتهم، ملاحقة مرتكبي الفساد، مكافحة اغتيال الشخصية\n⭐ التأكد من قيام مؤسسات الرقابة على القطاع الخاص ومؤسسات المجتمع المدني بوضع معايير الحوكمة الرشيدة","qs":[{"q":"أي مما يلي يعد من أهداف هيئة النزاهة ومكافحة الفساد وفق القانون؟","o":["مكافحة اغتيال الشخصية","الفصل في المنازعات بين الأفراد","إصدار الأحكام القضائية في قضايا الفساد","تدقيق حسابات الإدارة العامة بدلاً من ديوان المحاسبة"],"a":0},{"q":"أي مما يلي ليس من أهداف هيئة النزاهة ومكافحة الفساد وفق المادة (4)؟","o":["وضع معايير الحوكمة الرشيدة للقطاع الخاص بنفسها","تلقي شكاوى المتضررين وتظلماتهم","ملاحقة كل من يرتكب أياً من أفعال الفساد","التعاون في تقديم وطلب المساعدة القانونية الدولية في مجال مكافحة الفساد"],"a":0},{"q":"تتأكد الهيئة من التزام السلطة التنفيذية بالشفافية عند وضع السياسات واتخاذ القرارات وضمان حق المواطن في:","o":["الاطلاع على المعلومات وفقاً للتشريعات","الطعن في القرارات أمام الهيئة مباشرة","التعويض عن القرارات الإدارية","المشاركة في التصويت على القرارات"],"a":0}]},{"n":"5","chapter":"","source":"أ. تمارس الهيئة مهامها وأعمالها بحرية واستقلال دون تأثير أو تدخل من أي جهة.\nب. لأيجوز تفتيش مقر الهيئة إلا بأمر قضائي وبحضور المدعي العام المختص على ان يتم تبليغ\nالرئيس بذلك ودعوة من يمثل الهيئة لحضور التفتيش» ويعتبر باطلا أي اجراء مخالف لذلك.","notes":[],"title":"استقلال الهيئة وتفتيش مقرها","memo":"⭐ تمارس الهيئة مهامها بحرية واستقلال دون تأثير أو تدخل من أي جهة\n⭐ لا يجوز تفتيش مقرها إلا بأمر قضائي وبحضور المدعي العام المختص مع تبليغ الرئيس ودعوة من يمثل الهيئة\n⭐ أي إجراء مخالف لذلك يعتبر باطلاً","qs":[{"q":"لا يجوز تفتيش مقر هيئة النزاهة ومكافحة الفساد إلا:","o":["بأمر قضائي وبحضور المدعي العام المختص","بقرار من مجلس الوزراء","بموافقة رئيس الهيئة الخطية فقط","بقرار من المجلس القضائي وبحضور رئيس الهيئة"],"a":0},{"q":"جرى تفتيش مقر الهيئة بأمر قضائي وبحضور المدعي العام دون تبليغ الرئيس أو دعوة من يمثل الهيئة، فإن هذا الإجراء:","o":["يعتبر باطلاً","صحيح لصدوره بأمر قضائي","صحيح مع استحقاق الهيئة للتعويض","قابل للإبطال بقرار من مجلس الوزراء"],"a":0}]},{"n":"6","chapter":"","source":"أ.1. يتولى إدارة الهيئة والإشراف على شؤونها مجلس يتكون من رئيس وأربعة أعضاء ممن يتصفون بالعدالة والنزاهة والحيدة والخبرة ولا يحمل أي منهم جنسية أخرى ويتم تعيينهم بإرادة ملكية سامية بناء على تنسيب رئيس الوزراء.\n2. تكون مدة العضوية في المجلس أربع سنوات قابلة للتجديد لمرة واحدة للرئيس أو لعضو المجلس.\nب. على الرئيس وأعضاء المجلس ان يتفرغوا لعملهم ولا يجوز لأي منهم ممارسة أي عمل أو وظيفة أو مهنة كما لا يجوز أن يكون أي منهم معاراً أو منتدباً أو مكلفاً أو مجازاً من أي جهة.\nج.1. يتقاضى الرئيس الراتب والعلاوات المقررة لرئيس محكمة التمييز بمقتضى أحكام التشريعات النافذة.\n2. يتقاضى عضو المجلس الراتب والعلاوات المقررة لنائب رئيس محكمة التمييز بمقتضى أحكام التشريعات النافذة.\nد. يختار المجلس من بين أعضائه نائباً للرئيس يتولى مهامه عند غيابه.\nهـ. يطبق على الرئيس وأعضاء المجلس قانون الكسب غير المشروع.\nو. يقسم الرئيس وأعضاء المجلس قبل مباشرتهم أعمالهم أمام الملك اليمين التالية:\n\"أقسم بالله العظيم أن أكون مخلصاً للملك والوطن وأن أحافظ على الدستور وأحترم القوانين والأنظمة وأقوم بالمهام الموكولة إلي بحياد وصدق وأمانة.\"\nز. باستثناء حالات التلبس بالجرم؛ لا يجوز ملاحقة أو توقيف الرئيس أو عضو المجلس إلا بعد الحصول على إذن مسبق من المجلس القضائي وللمجلس القضائي أن يقرر بعد سماع أقوال الرئيس أو العضو استمرار توقيفه للمدة التي يراها مناسبة أو تمديدها أو الإفراج عنه بكفالة أو بغير كفالة.","notes":[],"title":"مجلس الهيئة: تشكيله وأحكامه","memo":"⭐ المجلس: رئيس وأربعة أعضاء، لا يحمل أي منهم جنسية أخرى، يعينون بإرادة ملكية سامية بتنسيب رئيس الوزراء\n⭐ مدة العضوية أربع سنوات قابلة للتجديد لمرة واحدة\n⭐ راتب الرئيس = رئيس محكمة التمييز، والعضو = نائب رئيس محكمة التمييز؛ ويطبق عليهم قانون الكسب غير المشروع\n⭐ لا يلاحقون أو يوقفون إلا بإذن مسبق من المجلس القضائي (باستثناء التلبس)","qs":[{"q":"يتكون مجلس هيئة النزاهة ومكافحة الفساد من:","o":["رئيس وأربعة أعضاء","رئيس وستة أعضاء","رئيس وثلاثة أعضاء","رئيس ونائب وخمسة أعضاء"],"a":0},{"q":"مدة العضوية في مجلس هيئة النزاهة ومكافحة الفساد:","o":["أربع سنوات قابلة للتجديد لمرة واحدة","ست سنوات غير قابلة للتجديد","أربع سنوات قابلة للتجديد دون حد","ثلاث سنوات قابلة للتجديد لمرة واحدة"],"a":0},{"q":"يتقاضى عضو مجلس الهيئة الراتب والعلاوات المقررة لـ:","o":["نائب رئيس محكمة التمييز","رئيس محكمة التمييز","قاضي محكمة التمييز","رئيس محكمة الاستئناف"],"a":0},{"q":"باستثناء حالات التلبس بالجرم، لا يجوز ملاحقة أو توقيف رئيس الهيئة أو عضو المجلس إلا بعد الحصول على إذن مسبق من:","o":["المجلس القضائي","مجلس الوزراء","مجلس النواب","النائب العام"],"a":0}]},{"n":"7","chapter":"","source":"أ. تنتهي خدمة الرئيس أو عضو المجلس بالاستقالة على ان يسري مفعولها من تاريخ صدور\nالارادة الملكية بقبولها.\nب. لمجلس الوزراء بناء على تنسيب المجلس أنهاء خدمة الرئيس أو أي عضو من اعضائه خلال\nمدة المجلس في أي من الحالات التالية:\n1. إذا أخل بواجبات الوظيفة والمهام الموكولة إليه أو قام بعمل يمس الشرف أو الكرامة.\n2. إذا ارتكب أي فعل أو تصرف يخل بمبادىء النزاهة الوطنية أو يدخل في نطاق الفساد وفق\nأحكام هذا القانون.\n3. إذا تغيب عن اجتماعات المجلس ثلاث جلسات متتالية أو ست جلسات متفرقة خلال السنة\nالوأحدة دون عذر يقبله المجلس.\nج. إذا شغر موقع الرئيس أو أي عضو من أعضاء المجلس لأي سبب من الأسباب يتم تعيين بديل\nعنه بالطريقة المنصوص عليها في البند (1) من الفقرة (أ) من المادة (6) من هذا القانون\nلإكمال المدة المتبقية من مدة المجلس.\nد. مع مراعاة أحكام الفقرتين (أ) و (ب) من هذه المادة, لأيجوز إحالة الرئيس أو أي عضو من\nأعضاء المجلس على التقاعد أو إنهاء خدماته قبل انتهاء مدة العضوية المنصوص عليها في هذا\nالقانون.","notes":[],"title":"انتهاء خدمة الرئيس أو العضو","memo":"⭐ الاستقالة تسري من تاريخ صدور الإرادة الملكية بقبولها\n⭐ إنهاء الخدمة: مجلس الوزراء بتنسيب المجلس (إخلال بالواجبات، فساد، غياب)\n⭐ الغياب: ثلاث جلسات متتالية أو ست جلسات متفرقة خلال السنة دون عذر يقبله المجلس\n⭐ البديل يعين بالطريقة ذاتها لإكمال المدة المتبقية","qs":[{"q":"يسري مفعول استقالة رئيس الهيئة أو عضو المجلس من تاريخ:","o":["صدور الإرادة الملكية بقبولها","تقديمها إلى المجلس","موافقة مجلس الوزراء عليها","نشرها في الجريدة الرسمية"],"a":0},{"q":"يجوز إنهاء خدمة عضو مجلس الهيئة إذا تغيب دون عذر يقبله المجلس عن:","o":["ثلاث جلسات متتالية أو ست جلسات متفرقة خلال السنة الواحدة","جلستين متتاليتين أو أربع جلسات متفرقة خلال السنة الواحدة","أربع جلسات متتالية أو ثماني جلسات متفرقة خلال السنة الواحدة","خمس جلسات متتالية أو عشر جلسات متفرقة خلال السنة الواحدة"],"a":0},{"q":"الجهة التي تملك إنهاء خدمة رئيس الهيئة أو أي عضو خلال مدة المجلس في الحالات المحددة قانوناً هي:","o":["مجلس الوزراء بناء على تنسيب المجلس","رئيس الوزراء بناء على تنسيب الرئيس","المجلس القضائي بناء على تنسيب مجلس الوزراء","مجلس الهيئة بأغلبية أعضائه"],"a":0}]},{"n":"8","chapter":"","source":"أ. يتولى المجلس المهام والصلاحيات التالية:\n1. وضع السياسة العامة للهيئة وإقرار الخطط والبرامج اللازمة لتنفيذها.\n2. إقرار معايير النزاهة الوطنية والتوعية بها.\n3. دراسة أي موضوع يعرض عليه، أو بمبادرة منه، يتعلق بأي من قرارات الإدارة العامة أو إجراءاتها أو ممارساتها وإرسال توصياتها بخصوصها إليه.\n4. التعاون والتنسيق مع الجهات المحلية والإقليمية والدولية المماثلة لعمل الهيئة.\n5. اتخاذ القرارات اللازمة بخصوص الشكاوى والتظلمات المقدمة إلى الهيئة بما في ذلك إحالتها إلى الجهات المختصة.\n6. اتخاذ القرارات اللازمة بخصوص قضايا الفساد بما في ذلك إحالتها إلى الجهات القضائية المختصة.\n7. الطلب من الجهات المعنية وقف كل من يرتكب أياً من أفعال الفساد عن العمل وفقاً لأحكام التشريعات النافذة.\n8. إجراء التحريات اللازمة لمتابعة أي من قضايا الفساد من تلقاء نفسه أو بناء على إخبار يرد من أي جهة، وإذا تبين بنتيجة التحري أو التحقيق أن الإخبار الوارد إليه كان كاذباً وكيدياً يتم تحويل مقدمه إلى الجهات القضائية المختصة وفقاً للأصول القانونية المتبعة.\n9. توعية المواطنين بالآثار السلبية للفساد على التنمية الاقتصادية والاجتماعية والسياسية.\n10. إصدار نشرات دورية تبين مخاطر الفساد والواسطة والمحسوبية على مؤسسات الدولة وإداراتها العامة.\n11. الموافقة على العقود والاتفاقيات التي تبرمها الهيئة.\n12. إقرار الهيكل التنظيمي للهيئة والموافقة على جدول تشكيلات الوظائف فيها لإقراره حسب الأصول.\n13. اقتراح مشروعات التشريعات الخاصة بعمل الهيئة ورفعها لمجلس الوزراء.\n14. إصدار التعليمات اللازمة لإدارة الهيئة بما في ذلك المتعلقة منها بمهام أعضاء المجلس وصلاحياتهم.\n15. تشكيل اللجان اللازمة لمساعدته على القيام بأعماله على أن يحدد في قرار تشكيلها عدد أعضائها ومهامها وكيفية اتخاذ قراراتها.\n16. إقرار البيانات المالية الختامية للهيئة والموافقة على مشروع الموازنة السنوية ورفعه لمجلس الوزراء لإقراره حسب الأصول.\n17. إقرار التقرير السنوي عن عمل الهيئة ورفعه إلى الملك ومجلس الوزراء ومجلسي الأعيان والنواب.\n18. أي أمور أخرى ذات علاقة بعمل الهيئة وأهدافها يعرضها الرئيس عليه.\nب. الطلب من الجهة القضائية المختصة إصدار قرار مستعجل بالحجز على الأموال المنقولة وغير المنقولة ومنع سفر كل من يرتكب أياً من أفعال الفساد أو الطلب بتعديل تلك القرارات أو إلغائها وفقاً للتشريعات النافذة.\nج. إذا تبين للمجلس وجود أدلة على نمو غير طبيعي في ثروة أي من المشمولين بأحكام قانون الكسب غير المشروع فله أن يطلب من دائرة إشهار الذمة المالية تزويده بصورة طبق الأصل عن الإقرارات وأي بيانات أو معلومات تتعلق بذلك الشخص.\nد. للمجلس المساهمة في استرداد الأموال المتحصلة عن أفعال الفساد سواء كانت الأموال داخل المملكة أو خارجها وتسليمها لمستحقيها وفق التشريعات ذات العلاقة.","notes":[],"title":"مهام وصلاحيات المجلس","memo":"⭐ يضع السياسة العامة، ويقر معايير النزاهة الوطنية، ويحيل قضايا الفساد إلى الجهات القضائية المختصة\n⭐ الإخبار الكاذب والكيدي: يحول مقدمه إلى الجهات القضائية المختصة\n⭐ يطلب من الجهة القضائية قراراً مستعجلاً بالحجز على الأموال ومنع السفر\n⭐ عند نمو غير طبيعي في الثروة يطلب صورة الإقرارات من دائرة إشهار الذمة المالية؛ والتقرير السنوي يرفع إلى الملك ومجلس الوزراء ومجلسي الأعيان والنواب","qs":[{"q":"إذا تبين لمجلس الهيئة بنتيجة التحري أن الإخبار الوارد إليه كان كاذباً وكيدياً، فإنه:","o":["يحول مقدمه إلى الجهات القضائية المختصة","يفرض عليه غرامة إدارية","يكتفي بحفظ الإخبار","يحيله إلى مجلس الوزراء"],"a":0},{"q":"إذا تبين لمجلس الهيئة وجود أدلة على نمو غير طبيعي في ثروة أحد المشمولين بقانون الكسب غير المشروع، فله أن يطلب صورة طبق الأصل عن الإقرارات من:","o":["دائرة إشهار الذمة المالية","دائرة ضريبة الدخل والمبيعات","البنك المركزي","ديوان المحاسبة"],"a":0},{"q":"يطلب مجلس الهيئة إصدار قرار مستعجل بالحجز على أموال مرتكب الفساد ومنع سفره من:","o":["الجهة القضائية المختصة","وزير الداخلية","مجلس الوزراء","مدير الأمن العام"],"a":0},{"q":"يرفع مجلس الهيئة التقرير السنوي عن عمل الهيئة بعد إقراره إلى:","o":["الملك ومجلس الوزراء ومجلسي الأعيان والنواب","رئيس الوزراء فقط","مجلس الوزراء وديوان المحاسبة","المجلس القضائي ومجلس النواب"],"a":0}]},{"n":"9","chapter":"","source":"أ. يجتمع المجلس بدعوة من رئيسه أو نائبه عند غيابه كلما دعت الحاجة» ويكون اجتماعه قانونيا\nبحضور أغلبية أعضائه على أن يكون الرئيس أو نائبه من بينهم ويتخذ قراراته بأغلبية أصوات\nأعضائه.\nب. يسمي الرئيس من بين موظفي الهيئة أمين سر للمجلس يتولى تنظيم جدول اعماله وتدوين\nمحاضر جلساته وقراراته وحفظ قيوده وسجلاته.\nقانون النزاهة ومكافحة الفساد وتعديلاته 2","notes":[],"title":"اجتماعات المجلس وأمين السر","memo":"⭐ يجتمع بدعوة من رئيسه أو نائبه عند غيابه\n⭐ النصاب: أغلبية أعضائه على أن يكون الرئيس أو نائبه من بينهم، والقرارات بأغلبية أصوات أعضائه\n⭐ الرئيس يسمي أمين سر المجلس من بين موظفي الهيئة","qs":[{"q":"يكون اجتماع مجلس الهيئة قانونياً بحضور:","o":["أغلبية أعضائه على أن يكون الرئيس أو نائبه من بينهم","ثلثي أعضائه على أن يكون الرئيس من بينهم","جميع أعضائه","ثلاثة أعضاء على الأقل بغض النظر عن حضور الرئيس أو نائبه"],"a":0},{"q":"يسمي أمين سر مجلس الهيئة من بين موظفي الهيئة:","o":["الرئيس","الأمين العام","المجلس بأغلبية أعضائه","مجلس الوزراء"],"a":0}]},{"n":"9 مكرر","chapter":"","source":"يتولى الرئيس المهام والصلاحيات التالية:\nأ. الإشراف على سير أعمال الهيئة بما في ذلك شؤونها الإدارية والمالية ومتابعة أعمالها.\nب. تنفيذ الخطط والبرامج والقرارات التي يصدرها المجلس.\nج. تمثيل الهيئة لدى الغير وتوقيع العقود والاتفاقيات التي يوافق عليها المجلس والإشراف على تنفيذها.\nد. اقتراح التعليمات اللازمة لإدارة الهيئة وعرضها على المجلس لإصدارها.\nهـ. أي مهام أخرى يكلفه بها المجلس أو ورد النص عليها في هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","notes":[],"title":"مهام وصلاحيات الرئيس","memo":"⭐ الإشراف على سير أعمال الهيئة وشؤونها الإدارية والمالية\n⭐ تنفيذ خطط المجلس وقراراته وتمثيل الهيئة لدى الغير وتوقيع العقود التي يوافق عليها المجلس\n⭐ يقترح التعليمات ويعرضها على المجلس لإصدارها","qs":[{"q":"يوقع رئيس الهيئة العقود والاتفاقيات:","o":["التي يوافق عليها المجلس","التي يوافق عليها مجلس الوزراء","التي يقترحها الأمين العام دون حاجة لموافقة","بعد مصادقة ديوان المحاسبة عليها"],"a":0},{"q":"بالنسبة للتعليمات اللازمة لإدارة الهيئة، فإن دور الرئيس هو:","o":["اقتراحها وعرضها على المجلس لإصدارها","إصدارها مباشرة دون الرجوع للمجلس","إقرارها بعد اقتراح الأمين العام","رفعها لمجلس الوزراء لإصدارها"],"a":0}]},{"n":"10","chapter":"","source":"أ. يعين للهيئة أمين عام بقرار من مجلس الوزراء بناء على تنسيب الرئيس.\nب. يتولى الأمين العام المهام والصلاحيات التالية:\n1. إدارة الجهاز التنفيذي للهيئة وفق الأنظمة والتعليمات الصادرة لهذه الغاية.\n2. اقتراح الهيكل التنظيمي للجهاز التنفيذي في الهيئة وجدول تشكيلات الوظائف فيها والوصف الوظيفي لها وعرضها على المجلس.\n3. إعداد مشروع الموازنة السنوية والتقرير السنوي عن أعمال الهيئة وبياناتها المالية الختامية وعرضها على المجلس لإقرارها.\n4. أي مهام أخرى يكلفه بها الرئيس أو ورد النص عليها في هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","notes":[],"title":"الأمين العام للهيئة","memo":"⭐ يعين بقرار من مجلس الوزراء بناء على تنسيب الرئيس\n⭐ يدير الجهاز التنفيذي ويقترح الهيكل التنظيمي وجدول التشكيلات ويعرضها على المجلس\n⭐ يعد مشروع الموازنة والتقرير السنوي والبيانات المالية الختامية ويعرضها على المجلس لإقرارها","qs":[{"q":"يعين أمين عام هيئة النزاهة ومكافحة الفساد بقرار من:","o":["مجلس الوزراء بناء على تنسيب الرئيس","مجلس الهيئة بناء على تنسيب الرئيس","الرئيس بناء على تنسيب المجلس","رئيس الوزراء بناء على تنسيب مجلس الهيئة"],"a":0},{"q":"يتولى إعداد مشروع الموازنة السنوية للهيئة وعرضه على المجلس:","o":["الأمين العام","الرئيس","أمين سر المجلس","ديوان المحاسبة"],"a":0},{"q":"أي مما يلي ليس من مهام الأمين العام للهيئة؟","o":["إقرار الهيكل التنظيمي للهيئة","إدارة الجهاز التنفيذي للهيئة","اقتراح الهيكل التنظيمي للجهاز التنفيذي","إعداد التقرير السنوي عن أعمال الهيئة"],"a":0}]},{"n":"11","chapter":"","source":"أ. يحق للمتضرر من قرارات الإدارة العامة أو الإجراءات أو الممارسات أو أفعال الامتناع عن أي منها أن يتقدم بتظلم في مواجهة الإدارة العامة أمام الهيئة وفقاً لأحكام هذا القانون.\nب. تقدم التظلمات متضمنة خلاصة الوقائع والأسباب والجهة التي أصدرت القرار أو اتخذت الإجراء على النموذج المعد لهذه الغاية، معززة بالوثائق والمستندات المؤيدة لها إن وجدت، على أن يكون هذا النموذج موقعاً من مقدم التظلم أو ممن يمثله قانوناً.\nج. تباشر الهيئة التحقق من التظلمات المقدمة إليها ويصدر المجلس قراره بقبول التظلم أو رفضه خلال مدة خمسة عشر يوماً من تاريخ ورودها للهيئة، على أن يكون قراره مسبباً في أي من هاتين الحالتين.\nد. في حال صدور قرار من المجلس بقبول التظلم، يفوض المجلس الرئيس أو أياً من أعضائه اتخاذ الإجراءات اللازمة لحل موضوع التظلم بالسرعة الممكنة وبالوسائل التي يراها مناسبة.\nهـ. تطبق على الرئيس أو العضو المحال إليه التظلم حالات عدم الصلاحية أو الرد أو التنحي المنصوص عليها في قانون أصول المحاكمات المدنية.","notes":[],"title":"التظلم من قرارات الإدارة العامة","memo":"⭐ للمتضرر من قرارات الإدارة العامة أو إجراءاتها أو ممارساتها أو الامتناع عنها التظلم أمام الهيئة\n⭐ يقدم على النموذج المعد موقعاً من مقدمه أو ممثله القانوني\n⭐ يصدر المجلس قراره بقبول التظلم أو رفضه خلال خمسة عشر يوماً من وروده، مسبباً\n⭐ تطبق على الرئيس أو العضو المحال إليه التظلم حالات عدم الصلاحية والرد والتنحي في قانون أصول المحاكمات المدنية","qs":[{"q":"يصدر مجلس الهيئة قراره بقبول التظلم أو رفضه خلال مدة:","o":["خمسة عشر يوماً من تاريخ وروده للهيئة","ثلاثين يوماً من تاريخ وروده للهيئة","ستة أشهر من تاريخ وروده للهيئة","سبعة أيام من تاريخ وروده للهيئة"],"a":0},{"q":"قرار مجلس الهيئة بشأن التظلم يجب أن يكون مسبباً:","o":["في حالتي القبول والرفض","في حالة الرفض فقط","في حالة القبول فقط","إذا طلب المتظلم ذلك فقط"],"a":0},{"q":"تطبق على الرئيس أو العضو المحال إليه التظلم حالات عدم الصلاحية أو الرد أو التنحي المنصوص عليها في:","o":["قانون أصول المحاكمات المدنية","قانون أصول المحاكمات الجزائية","نظام الخدمة المدنية","قانون العقوبات"],"a":0}]},{"n":"12","chapter":"","source":"أ. إذا تبين أن التظلم المقدم وفقاً لأحكام هذا القانون ينطوي على جريمة جزائية، فيترتب على المجلس إحالة الملف إلى المدعي العام المختص أو إلى المحكمة المختصة.\nب. لا يقبل التظلم بعد ستة أشهر على الواقعة، وللمجلس قبوله بعد انقضاء المدة المذكورة إذا وجد أن موضوعه يتعلق بأمر عام.","notes":[],"title":"إحالة التظلم الجزائي ومدة قبوله","memo":"⭐ إذا انطوى التظلم على جريمة جزائية يحيل المجلس الملف إلى المدعي العام المختص أو المحكمة المختصة\n⭐ لا يقبل التظلم بعد ستة أشهر على الواقعة، إلا إذا تعلق موضوعه بأمر عام","qs":[{"q":"لا يقبل التظلم أمام الهيئة بعد مرور:","o":["ستة أشهر على الواقعة","ثلاثة أشهر على الواقعة","سنة على الواقعة","خمسة عشر يوماً على الواقعة"],"a":0},{"q":"قدم مواطن تظلماً بعد ثمانية أشهر من الواقعة وتبين أن موضوعه يتعلق بأمر عام، فإن للمجلس:","o":["قبوله رغم انقضاء المدة","رفضه وجوباً لانقضاء المدة","إحالته إلى مجلس الوزراء","إحالته إلى المحكمة الإدارية"],"a":0},{"q":"إذا تبين أن التظلم المقدم للهيئة ينطوي على جريمة جزائية، يترتب على المجلس إحالة الملف إلى:","o":["المدعي العام المختص أو المحكمة المختصة","مجلس الوزراء","الإدارة العامة المشكو منها","ديوان المحاسبة"],"a":0}]},{"n":"13","chapter":"","source":"أ. إذا تبين للمجلس بعد استكمال إجراءاته بأن قرارات الإدارة العامة أو إجراءاتها أو الامتناع عن القيام بها تتضمن أياً مما يلي:\n1. مخالفة التشريعات.\n2. عدم الإنصاف أو التعسف أو عدم تحقيق المساواة والتمييز.\n3. الاستناد إلى تعليمات غير قانونية أو إجراءات غير عادلة.\n4. الإهمال أو التقصير أو الخطأ. فعلى الرئيس كتابة تقرير مفصل بها وإرساله إلى الإدارة العامة المشكو منها وله الحق في تقديم التوصيات التي يراها مناسبة حول موضوع التظلم.\nب. على الإدارة العامة الرد خلال خمسة عشر يوماً من تاريخ تسلمها التقرير المشار إليه في الفقرة (أ) من هذه المادة ولها الطلب من الرئيس تمديد هذه المدة لمدة مماثلة.\nج. إذا امتنعت الإدارة العامة عن الرد خلال المدة المحددة في الفقرة (ب) من هذه المادة أو رفضت اتخاذ الإجراءات اللازمة أو وقع خلاف بين الهيئة والإدارة العامة يحيل الرئيس الأمر إلى مجلس الوزراء لاتخاذ القرار الذي يراه مناسباً.","notes":[],"title":"نتائج التحقق من التظلمات","memo":"⭐ عند ثبوت المخالفة يكتب الرئيس تقريراً مفصلاً للإدارة المشكو منها مع توصيات\n⭐ على الإدارة الرد خلال خمسة عشر يوماً من تسلم التقرير، ولها طلب التمديد من الرئيس لمدة مماثلة\n⭐ عند الامتناع أو الرفض أو الخلاف يحيل الرئيس الأمر إلى مجلس الوزراء","qs":[{"q":"على الإدارة العامة الرد على تقرير رئيس الهيئة بشأن التظلم خلال:","o":["خمسة عشر يوماً من تاريخ تسلمها التقرير","ثلاثين يوماً من تاريخ تسلمها التقرير","سبعة أيام من تاريخ تسلمها التقرير","ستين يوماً من تاريخ تسلمها التقرير"],"a":0},{"q":"إذا امتنعت الإدارة العامة عن الرد على تقرير الهيئة خلال المدة المحددة أو وقع خلاف بينها وبين الهيئة، يحيل الرئيس الأمر إلى:","o":["مجلس الوزراء","المحكمة الإدارية","المجلس القضائي","مجلس النواب"],"a":0},{"q":"يجوز للإدارة العامة طلب تمديد مدة الرد على تقرير الهيئة:","o":["من الرئيس لمدة مماثلة","من المجلس لمدة ستة أشهر","من مجلس الوزراء لمدة ثلاثين يوماً","ولا يجوز التمديد مطلقاً"],"a":0}]},{"n":"14","chapter":"","source":"أ. للرئيس تعيين ضابط ارتباط واحد أو أكثر لدى الإدارة العامة للتحقق من مدى التزامها بمعايير النزاهة الوطنية والتشريعات ولمتابعة التظلمات من قراراتها.\nب. يجوز لضابط الارتباط حضور اجتماعات لجان العطاءات والمشتريات وأي لجان أخرى في الإدارة العامة دون أن يكون له حق التصويت على القرارات.\nج. تحدد سائر الشؤون المتعلقة بضابط الارتباط بمقتضى تعليمات يصدرها المجلس لهذه الغاية.","notes":[],"title":"ضابط الارتباط","memo":"⭐ يعينه الرئيس (واحد أو أكثر) لدى الإدارة العامة\n⭐ يحضر اجتماعات لجان العطاءات والمشتريات وغيرها دون حق التصويت\n⭐ تحدد شؤونه بتعليمات يصدرها المجلس","qs":[{"q":"يعين ضابط الارتباط لدى الإدارة العامة من قبل:","o":["رئيس الهيئة","مجلس الوزراء","الوزير المختص","الأمين العام للهيئة"],"a":0},{"q":"لضابط الارتباط حضور اجتماعات لجان العطاءات والمشتريات في الإدارة العامة:","o":["دون أن يكون له حق التصويت على القرارات","مع حق التصويت على القرارات","بصفته رئيساً للجنة","بشرط موافقة الوزير المختص"],"a":0},{"q":"تحدد سائر الشؤون المتعلقة بضابط الارتباط بمقتضى:","o":["تعليمات يصدرها المجلس","نظام يصدره مجلس الوزراء","قرار من رئيس الوزراء","تعليمات يصدرها الأمين العام"],"a":0}]},{"n":"15","chapter":"","source":"أ. تلتزم الإدارة العامة بتطبيق مبادئ الشفافية وقيمها في العلانية والإفصاح في أداء مهامها\nالتنظيمية والإجرائية وتوظيف كوادرها وفي علاقاتها الداخلية والخارجية وتعاقداتها.\nب. على الإدارة العامة توفير نافذة خاصة بالمعلومات العامة تكون متاحة لاطلاع المواطنين عليها\nوذلك مع مراعاة أحكام التشريعات ذات العلاقة.\nقانون النزاهة ومكافحة الفساد وتعديلاته 2","notes":[],"title":"الشفافية في الإدارة العامة","memo":"⭐ تلتزم الإدارة العامة بمبادئ الشفافية في العلانية والإفصاح في مهامها وتوظيف كوادرها وتعاقداتها\n⭐ عليها توفير نافذة خاصة بالمعلومات العامة متاحة لاطلاع المواطنين","qs":[{"q":"يتوجب على الإدارة العامة وفق قانون النزاهة ومكافحة الفساد توفير:","o":["نافذة خاصة بالمعلومات العامة متاحة لاطلاع المواطنين","ضابط ارتباط في كل دائرة على نفقتها","سجل لتلقي التظلمات يرفع للهيئة يومياً","تقرير شهري عن تعاقداتها للهيئة"],"a":0},{"q":"تطبق الإدارة العامة مبادئ الشفافية وقيمها في العلانية والإفصاح في أي مما يلي؟","o":["توظيف كوادرها وتعاقداتها","علاقاتها الخارجية فقط","تعاقداتها الخارجية فقط","مهامها التنظيمية فقط"],"a":0}]},{"n":"16","chapter":"","source":"أ. يعتبر فساداً لغايات هذا القانون ما يلي:\n1. الجرائم المخلة بواجبات الوظيفة والجرائم المخلة بالثقة العامة الواردة في قانون العقوبات.\n2. الجرائم الاقتصادية بالمعنى المحدد في قانون الجرائم الاقتصادية.\n3. الكسب غير المشروع.\n4. عدم الإعلان أو الإفصاح عن استثمارات أو ممتلكات أو منافع قد تؤدي إلى تعارض في المصالح إذا كانت القوانين والأنظمة تستوجب ذلك ويكون من شأنها تحقيق منفعة شخصية مباشرة أو غير مباشرة للممتنع عن إعلانها.\n5. كل فعل أو امتناع يؤدي إلى هدر الأموال العامة أو أموال الشركات المساهمة العامة أو الشركات غير الربحية أو الجمعيات.\n6. إساءة استعمال السلطة خلافاً لأحكام القانون.\n7. قبول موظفي الإدارة العامة للواسطة والمحسوبية التي تلغي حقاً أو تحقق باطلاً.\n8. استخدام المعلومات المتاحة بحكم الوظيفة لتحقيق منافع خاصة.\n9. جرائم الفساد الواردة في الاتفاقيات الدولية التي صادقت عليها المملكة.\nب. مع مراعاة ما ورد في الفقرة (أ) من هذه المادة، لا تختص الهيئة بالنظر فيما يلي:\n1. المنازعات والشكاوى بين الأفراد.\n2. الشكاوى التي تدخل في اختصاص أي جهة رسمية رقابية أخرى والتي يتوجب عليها إذا ظهر أي فعل ينطوي على جرم جزائي في أثناء ممارستها لأعمالها إحالة مرتكب هذا الفعل للنيابة العامة.\n3. الشكاوى والتظلمات القابلة للطعن الإداري أو القضائي أو المنظورة أمام جهة قضائية أو صدرت أحكام قضائية فيها.\nج. تسري الأحكام الخاصة الواردة في التشريعات ذات العلاقة في حال كان المشتكى عليه بالفساد أحد الأشخاص الذين يستوجب الدستور أو التشريعات ذات العلاقة شكلاً أو إجراءات خاصة للتحقيق معه أو ملاحقته قضائياً.","notes":[],"title":"أفعال الفساد وما لا تختص به الهيئة","memo":"⭐ من الفساد: الجرائم المخلة بواجبات الوظيفة والثقة العامة، الجرائم الاقتصادية، الكسب غير المشروع، إساءة استعمال السلطة، الواسطة والمحسوبية التي تلغي حقاً أو تحقق باطلاً\n⭐ هدر الأموال العامة أو أموال الشركات المساهمة العامة أو غير الربحية أو الجمعيات\n⭐ لا تختص الهيئة بـ: المنازعات بين الأفراد، ما يدخل في اختصاص جهة رقابية أخرى، ما يقبل الطعن الإداري أو القضائي أو منظور أمام القضاء","qs":[{"q":"أي مما يلي يعتبر فساداً لغايات قانون النزاهة ومكافحة الفساد؟","o":["استخدام المعلومات المتاحة بحكم الوظيفة لتحقيق منافع خاصة","المنازعات المالية بين الأفراد","التأخر في سداد الضريبة","مخالفة الأنظمة المرورية"],"a":0},{"q":"تعتبر الواسطة والمحسوبية فساداً وفق القانون إذا:","o":["قبلها موظفو الإدارة العامة وكانت تلغي حقاً أو تحقق باطلاً","صدرت عن أي شخص ولو لم تؤثر في القرار","كانت لمصلحة أقارب الموظف حتى الدرجة الثانية فقط","تعلقت بالتعيين في الوظائف العليا فقط"],"a":0},{"q":"أي مما يلي لا تختص الهيئة بالنظر فيه؟","o":["الشكاوى المنظورة أمام جهة قضائية","الكسب غير المشروع","إساءة استعمال السلطة خلافاً لأحكام القانون","هدر أموال الشركات المساهمة العامة"],"a":0},{"q":"هدر الأموال الذي يعد فساداً وفق القانون يشمل أموال ما يلي باستثناء:","o":["الشركات ذات المسؤولية المحدودة","الشركات المساهمة العامة","الشركات غير الربحية","الجمعيات"],"a":0}]},{"n":"17","chapter":"","source":"أ. على الرغم مما ورد في أي قانون، يكون لدى النيابة العامة نيابة متخصصة بقضايا الفساد تتولى النظر في القضايا المحالة إليها من المجلس.\nب. يسمي المجلس القضائي في بداية كل سنة العدد اللازم من المدعين العامين للعمل في النيابة المتخصصة المشار إليها في الفقرة (أ) من هذه المادة.","notes":[],"title":"النيابة المتخصصة بقضايا الفساد","memo":"⭐ نيابة متخصصة بقضايا الفساد لدى النيابة العامة تنظر في القضايا المحالة من المجلس\n⭐ المجلس القضائي يسمي المدعين العامين في بداية كل سنة","qs":[{"q":"يسمي العدد اللازم من المدعين العامين للعمل في النيابة المتخصصة بقضايا الفساد:","o":["المجلس القضائي في بداية كل سنة","مجلس الهيئة في بداية كل سنة","وزير العدل كل سنتين","النائب العام عند الحاجة"],"a":0},{"q":"تنظر النيابة المتخصصة بقضايا الفساد في القضايا المحالة إليها من:","o":["مجلس الهيئة","مجلس الوزراء","ديوان المحاسبة","الإدارة العامة مباشرة"],"a":0}]},{"n":"18","chapter":"","source":"للرئيس طلب انتداب أو إعارة أو تكليف أي من ضباط أو أفراد الأجهزة الأمنية والعسكرية أو أي\nموظف من أي وزارة أو دائرة أو مؤسسة رسمية للعمل لدى الهيئة وفقاً للتشريعات النافذة.","notes":[],"title":"الانتداب والإعارة والتكليف للهيئة","memo":"⭐ للرئيس طلب انتداب أو إعارة أو تكليف ضباط أو أفراد الأجهزة الأمنية والعسكرية أو أي موظف رسمي للعمل لدى الهيئة وفق التشريعات النافذة","qs":[{"q":"صلاحية طلب انتداب أو إعارة أو تكليف أي من ضباط الأجهزة الأمنية للعمل لدى الهيئة تعود إلى:","o":["رئيس الهيئة","مجلس الوزراء","الأمين العام للهيئة","وزير الداخلية"],"a":0},{"q":"أي مما يلي يجوز لرئيس الهيئة طلب انتدابه أو إعارته أو تكليفه للعمل لدى الهيئة؟","o":["أفراد الأجهزة الأمنية والعسكرية","موظفو الشركات الخاصة","القضاة النظاميون","أعضاء مجلس النواب"],"a":0}]},{"n":"19","chapter":"","source":"يكون للرئيس وأعضاء المجلس صفة الضابطة العدلية، لغايات قيامهم بمهامهم، ويحدد المجلس العاملين في الهيئة الذين يتمتعون بهذه الصفة.","notes":[],"title":"صفة الضابطة العدلية","memo":"⭐ للرئيس وأعضاء المجلس صفة الضابطة العدلية لغايات قيامهم بمهامهم\n⭐ المجلس يحدد العاملين في الهيئة الذين يتمتعون بهذه الصفة","qs":[{"q":"يحدد العاملين في الهيئة الذين يتمتعون بصفة الضابطة العدلية:","o":["مجلس الهيئة","رئيس الهيئة منفرداً","النائب العام","المجلس القضائي"],"a":0},{"q":"يتمتع بصفة الضابطة العدلية بحكم القانون لغايات قيامهم بمهامهم:","o":["الرئيس وأعضاء المجلس","الأمين العام وأمين السر","ضباط الارتباط","جميع موظفي الهيئة"],"a":0}]},{"n":"20","chapter":"","source":"أ. مع مراعاة أحكام التشريعات النافذة، للهيئة في سبيل قيامها بمهامها طلب أي بيانات أو معلومات أو وثائق من أي شخص أو من أي جهة كانت، وعليهم الاستجابة للطلب دون إبطاء تحت طائلة المسؤولية القانونية.\nب. يعاقب على الامتناع أو التأخير غير المبرر عن تقديم البيانات أو المعلومات أو الوثائق المطلوبة وفقاً لأحكام الفقرة (أ) من هذه المادة بالحبس مدة لا تزيد على ثلاثة أشهر أو بغرامة لا تزيد على خمسمائة دينار.\nج. للهيئة الطلب من المؤسسات الرقابية الرسمية إجراء عمليات التدقيق والخبرة الفنية اللازمة على الجهات الخاضعة لرقابتها لتمكين الهيئة من القيام بمهامها.\nد. للهيئة في أثناء التحقيق في أي قضية فساد أن تكلف أياً من الأشخاص أو الشركات أو الجهات المتخصصة للقيام بأعمال التدقيق الفني والمالي والإداري على الجهات المشمولة بأحكام هذا القانون للتحقق من صحة بياناتها المالية وقيودها وحساباتها وجميع تصرفاتها المالية.","notes":[],"title":"طلب البيانات وأعمال التدقيق","memo":"⭐ للهيئة طلب أي بيانات أو معلومات أو وثائق من أي شخص أو جهة، وعليهم الاستجابة دون إبطاء\n⭐ الامتناع أو التأخير غير المبرر: حبس لا يزيد على ثلاثة أشهر أو غرامة لا تزيد على خمسمائة دينار\n⭐ للهيئة الطلب من المؤسسات الرقابية الرسمية التدقيق، وتكليف أشخاص أو شركات متخصصة بالتدقيق أثناء التحقيق","qs":[{"q":"عقوبة الامتناع أو التأخير غير المبرر عن تقديم البيانات أو المعلومات التي تطلبها الهيئة:","o":["الحبس مدة لا تزيد على ثلاثة أشهر أو غرامة لا تزيد على خمسمائة دينار","الحبس مدة لا تقل عن سنة","الحبس مدة لا تقل عن أربعة أشهر أو غرامة لا تقل عن خمسمائة دينار","غرامة لا تزيد على خمسة آلاف دينار فقط"],"a":0},{"q":"للهيئة في أثناء التحقيق في قضية فساد أن تكلف أشخاصاً أو شركات متخصصة للقيام بأعمال:","o":["التدقيق الفني والمالي والإداري على الجهات المشمولة بالقانون","التحقيق الجزائي بدلاً من النيابة العامة","الحجز على الأموال مباشرة","إصدار قرارات منع السفر"],"a":0},{"q":"للهيئة أن تطلب إجراء عمليات التدقيق والخبرة الفنية على الجهات الخاضعة لرقابتها من:","o":["المؤسسات الرقابية الرسمية","المحاكم المختصة","مجلس الوزراء","النيابة العامة"],"a":0}]},{"n":"21","chapter":"","source":"على الرغم مما ورد في أي تشريع آخر، تلتزم الهيئة بإصدار قراراتها في موعد لا يتجاوز ستة أشهر من تاريخ بدء إجراءات التحقيق والتحري في الشكوى، وللمجلس إذا اقتضت الضرورة تمديد ذلك الموعد لمدة إضافية مماثلة.","notes":[],"title":"مدة إصدار قرارات الهيئة","memo":"⭐ تصدر الهيئة قراراتها خلال مدة لا تتجاوز ستة أشهر من بدء التحقيق والتحري في الشكوى\n⭐ للمجلس عند الضرورة التمديد لمدة إضافية مماثلة","qs":[{"q":"تلتزم الهيئة بإصدار قراراتها في موعد لا يتجاوز:","o":["ستة أشهر من تاريخ بدء إجراءات التحقيق والتحري في الشكوى","ثلاثة أشهر من تاريخ ورود الشكوى","سنة من تاريخ بدء إجراءات التحقيق","خمسة عشر يوماً من تاريخ ورود الشكوى"],"a":0},{"q":"بدأت الهيئة التحقيق في شكوى واقتضت الضرورة تمديد موعد إصدار القرار، فإن للمجلس تمديده:","o":["لمدة إضافية مماثلة","لمدة إضافية لا تتجاوز ثلاثة أشهر","لمدة غير محددة","بعد موافقة مجلس الوزراء فقط"],"a":0}]},{"n":"22","chapter":"","source":"أ. تعتبر المعلومات والبيانات والوثائق ونسخها التي ترد للهيئة أو يطلع عليها أي من العاملين فيها بحكم وظائفهم سرية ولا يجوز إفشاؤها أو إبرازها أو السماح للغير بالاطلاع عليها إلا وفقاً لأحكام القانون.\nب. دون الإخلال بأي عقوبة أشد ورد النص عليها في أي تشريع آخر، يعاقب كل من يخالف أحكام الفقرة (أ) من هذه المادة بالحبس مدة لا تقل عن سنة.\nج. تسري أحكام هذه المادة على جميع العاملين في الهيئة وأي من المشار إليهم في المادة (18) والفقرة (ج) من المادة (20) من هذا القانون حتى بعد انتهاء عملهم فيها أو انتهاء المهمة الموكولة إليهم.\nد. على الرغم مما ورد في أي تشريع آخر، يعاقب بالحبس مدة لا تقل عن أربعة أشهر أو بغرامة لا تقل عن خمسمائة دينار ولا تزيد على خمسة آلاف دينار أو بكلتا هاتين العقوبتين كل موظف عام توافرت لديه أدلة عن وجود فساد ولم يقم بالإبلاغ عنها للهيئة أو للسلطات المختصة.","notes":[],"title":"سرية المعلومات وعدم الإبلاغ عن الفساد","memo":"⭐ معلومات الهيئة سرية؛ إفشاؤها: حبس لا يقل عن سنة\n⭐ يسري الالتزام على العاملين والمنتدبين والمدققين حتى بعد انتهاء عملهم\n⭐ الموظف العام الذي لديه أدلة فساد ولم يبلغ: حبس لا يقل عن أربعة أشهر أو غرامة 500-5000 دينار أو كلتاهما","qs":[{"q":"عقوبة إفشاء المعلومات والبيانات السرية التي ترد للهيئة:","o":["الحبس مدة لا تقل عن سنة","الحبس مدة لا تزيد على ثلاثة أشهر","الحبس مدة لا تقل عن ستة أشهر ولا تزيد على سنة","غرامة لا تزيد على خمسمائة دينار"],"a":0},{"q":"يعاقب الموظف العام الذي توافرت لديه أدلة عن وجود فساد ولم يقم بالإبلاغ عنها بالحبس مدة لا تقل عن أربعة أشهر أو بغرامة:","o":["لا تقل عن خمسمائة دينار ولا تزيد على خمسة آلاف دينار","لا تقل عن ألف دينار ولا تزيد على عشرة آلاف دينار","لا تزيد على خمسمائة دينار","لا تقل عن مئة دينار ولا تزيد على ألف دينار"],"a":0},{"q":"موظف انتهت إعارته للهيئة ثم أفشى معلومات سرية اطلع عليها أثناء عمله فيها، فإن حكم السرية:","o":["يسري عليه حتى بعد انتهاء عمله","لا يسري عليه لانتهاء إعارته","يسري عليه لمدة سنة فقط بعد انتهاء عمله","يسري عليه فقط إذا كان من موظفي الهيئة الأصليين"],"a":0}]},{"n":"23","chapter":"","source":"أ. دون الإخلال بأي عقوبة أشد ورد النص عليها في أي تشريع آخر يعاقب بالحبس مدة لا تقل عن أربعة أشهر أو بغرامة لا تقل عن خمسمائة دينار ولا تزيد على خمسة آلاف دينار أو بكلتا هاتين العقوبتين كل من ارتكب أياً من الأفعال والتصرفات المنصوص عليها في المادة (16) من هذا القانون وفي حال التكرار يضاف للعقوبة نصفها.\nب. مع مراعاة الاتفاقيات الدولية التي صادقت عليها المملكة، تسري أحكام الفقرة (أ) من هذه المادة على الموظف العمومي غير الأردني وعلى موظفي المؤسسات الدولية العمومية مع الإلزام برد الأموال المتحصلة عن أفعال الفساد.\nج.\n1. كل عقد أو اتفاق أو منفعة تم الحصول عليه نتيجة فعل يشكل فساداً يكون قابلاً للإبطال أو الفسخ بقرار من المحكمة المختصة.\n2. كل امتياز تم الحصول عليه نتيجة فعل يشكل فساداً يكون غير نافذ بقرار من المحكمة المختصة وعلى الجهات المختصة إلغاء قانون التصديق على الامتياز وفقاً للإجراءات الدستورية.\n3. للهيئة في أثناء إجراء تحقيقاتها أن تطلب كإجراء مستعجل من المحكمة المختصة وقف العمل بأي عقد أو اتفاق أو منفعة أو امتياز إذا تبين لها من ظاهر البينة أنه تم الحصول عليه نتيجة فعل فساد وذلك إلى حين البت في الدعوى.","notes":[],"title":"عقوبات الفساد وآثاره على العقود","memo":"⭐ عقوبة أفعال المادة (16): حبس لا يقل عن أربعة أشهر أو غرامة 500-5000 دينار أو كلتاهما؛ وفي التكرار يضاف للعقوبة نصفها\n⭐ تسري على الموظف العمومي غير الأردني وموظفي المؤسسات الدولية مع رد الأموال\n⭐ العقد أو المنفعة الناتجة عن فساد: قابلة للإبطال أو الفسخ بقرار المحكمة؛ والامتياز: غير نافذ\n⭐ للهيئة طلب وقف العمل بالعقد أو الامتياز كإجراء مستعجل من المحكمة المختصة","qs":[{"q":"في حال تكرار ارتكاب أي من أفعال الفساد المنصوص عليها في المادة (16):","o":["يضاف للعقوبة نصفها","تضاعف العقوبة","يضاف للعقوبة ثلثها","تكون العقوبة الحبس لمدة لا تقل عن سنتين"],"a":0},{"q":"كل عقد أو اتفاق تم الحصول عليه نتيجة فعل يشكل فساداً يكون:","o":["قابلاً للإبطال أو الفسخ بقرار من المحكمة المختصة","باطلاً بطلاناً مطلقاً بحكم القانون","موقوفاً على إجازة مجلس الوزراء","قابلاً للإبطال بقرار من مجلس الهيئة"],"a":0},{"q":"كل امتياز تم الحصول عليه نتيجة فعل يشكل فساداً يكون:","o":["غير نافذ بقرار من المحكمة المختصة","باطلاً بقرار من مجلس الهيئة","قابلاً للفسخ بقرار من مجلس الوزراء","نافذاً إلى حين تعديل قانون التصديق عليه"],"a":0},{"q":"يعاقب مرتكب أي من أفعال الفساد الواردة في المادة (16) بالحبس مدة:","o":["لا تقل عن أربعة أشهر أو بغرامة لا تقل عن 500 دينار ولا تزيد على 5000 دينار أو بكلتا العقوبتين","لا تزيد على ثلاثة أشهر أو بغرامة لا تزيد على 500 دينار","لا تقل عن سنة وبغرامة لا تتجاوز 10000 دينار","لا تقل عن ستة أشهر ولا تزيد على سنة"],"a":0}]},{"n":"24","chapter":"","source":"أ. تتولى الهيئة توفير الحماية اللازمة للمبلغين والشهود والمخبرين والخبراء في قضايا الفساد وأقاربهم والأشخاص وثيقي الصلة بهم من أي اعتداء أو انتقام أو ترهيب محتمل من خلال ما يلي:\n1. توفير الحماية لهم في أماكن إقامتهم.\n2. عدم الإفصاح عن المعلومات المتعلقة بهويتهم وأماكن وجودهم.\n3. الإدلاء بأقوالهم وشهاداتهم من خلال استخدام تقنيات الاتصال الحديثة وبما يكفل سلامتهم.\n4. حمايتهم في أماكن عملهم وتحصينهم من أي تمييز أو سوء معاملة أو فصل تعسفي.\n5. توفير أماكن لإيوائهم عند الضرورة.\n6. اتخاذ أي إجراء أو القيام بأي عمل ضروري يضمن سلامتهم.\nب. يتم البت بطلبات توفير الحماية من المجلس وفقاً لما تفرضه الظروف المحيطة بطالبي الحماية، على أن يتم رفع الحماية عنهم حال زوال الظروف التي أدت إلى فرضها.\nج. تنظم جميع الأمور المتعلقة بتوفير الحماية المطلوبة للمبلغين والشهود والمخبرين والخبراء وأقاربهم والأشخاص وثيقي الصلة بهم بمقتضى نظام يصدر لهذه الغاية.\nد. على الرغم مما ورد في أي تشريع آخر، للرئيس صرف مساعدات مالية للمبلغين والشهود والمخبرين الذين تقرر الهيئة حمايتهم بموجب تعليمات يصدرها المجلس لهذه الغاية.","notes":[],"title":"حماية المبلغين والشهود والمخبرين والخبراء","memo":"⭐ الحماية تشمل المبلغين والشهود والمخبرين والخبراء وأقاربهم والأشخاص وثيقي الصلة بهم\n⭐ يبت المجلس بطلبات الحماية وترفع حال زوال ظروفها، وتنظم بنظام\n⭐ للرئيس صرف مساعدات مالية للمبلغين والشهود والمخبرين المحميين بموجب تعليمات يصدرها المجلس","qs":[{"q":"يتم البت بطلبات توفير الحماية للمبلغين والشهود في قضايا الفساد من:","o":["مجلس الهيئة","رئيس الهيئة منفرداً","المدعي العام المختص","مديرية الأمن العام"],"a":0},{"q":"صرف المساعدات المالية للمبلغين والشهود والمخبرين الذين تقرر الهيئة حمايتهم يكون من قبل:","o":["الرئيس بموجب تعليمات يصدرها المجلس","مجلس الوزراء بموجب نظام","الأمين العام بموجب قرار من الرئيس","وزير المالية بتنسيب من الهيئة"],"a":0},{"q":"أي مما يلي ليس من وسائل الحماية المنصوص عليها في المادة (24)؟","o":["منح المحمي حصانة من الملاحقة القضائية","عدم الإفصاح عن المعلومات المتعلقة بهويتهم وأماكن وجودهم","الإدلاء بأقوالهم من خلال تقنيات الاتصال الحديثة","توفير أماكن لإيوائهم عند الضرورة"],"a":0}]},{"n":"25","chapter":"","source":"تسقط الحماية الممنوحة بقرار من المجلس في حال مخالفة شروط منحها أو في حال ارتكاب\nالشخص الممنوحة له الحماية لأي جناية أو جنحة مخلة بالشرف.","notes":[],"title":"سقوط الحماية","memo":"⭐ تسقط الحماية بقرار من المجلس عند مخالفة شروط منحها أو ارتكاب المحمي جناية أو جنحة مخلة بالشرف","qs":[{"q":"تسقط الحماية الممنوحة للمبلغ أو الشاهد بقرار من المجلس في حال:","o":["ارتكابه لأي جناية أو جنحة مخلة بالشرف","تقديمه شكوى جديدة للهيئة","انتهاء سنة على منحها","انتقاله للعمل في جهة أخرى"],"a":0},{"q":"الجهة المختصة بإسقاط الحماية الممنوحة عند مخالفة شروط منحها هي:","o":["مجلس الهيئة","المحكمة المختصة","المدعي العام","رئيس الوزراء"],"a":0}]},{"n":"26","chapter":"","source":"أ. يعاقب كل من أفشى معلومات متعلقة بهوية المبلغين أو الشهود أو المخبرين أو الخبراء أو بأماكن وجودهم بالحبس مدة لا تقل عن ستة أشهر ولا تزيد على سنة وبغرامة لا تتجاوز عشرة آلاف دينار.\nب. إذا أدى الإفشاء المنصوص عليه في الفقرة (أ) من هذه المادة إلى إلحاق جرم بأي من الأشخاص المنصوص عليهم في الفقرة ذاتها فيعتبر المفشي شريكاً في هذه الجريمة ويعاقب بالعقوبة المقررة للفاعل الأصلي.","notes":[],"title":"عقوبة إفشاء معلومات المحميين","memo":"⭐ إفشاء هوية المبلغين أو الشهود أو المخبرين أو الخبراء أو أماكن وجودهم: حبس من ستة أشهر إلى سنة وغرامة لا تتجاوز عشرة آلاف دينار\n⭐ إذا أدى الإفشاء إلى إلحاق جرم بهم يعتبر المفشي شريكاً ويعاقب بعقوبة الفاعل الأصلي","qs":[{"q":"عقوبة إفشاء معلومات متعلقة بهوية المبلغين أو الشهود أو أماكن وجودهم:","o":["الحبس من ستة أشهر إلى سنة وغرامة لا تتجاوز عشرة آلاف دينار","الحبس مدة لا تقل عن سنة","الحبس مدة لا تقل عن سنتين وغرامة لا تزيد على عشرة آلاف دينار","الحبس مدة لا تزيد على ثلاثة أشهر أو غرامة لا تزيد على خمسمائة دينار"],"a":0},{"q":"أفشى شخص مكان وجود أحد الشهود في قضية فساد فأدى ذلك إلى الاعتداء على الشاهد، فإن المفشي:","o":["يعتبر شريكاً ويعاقب بالعقوبة المقررة للفاعل الأصلي","يعاقب بنصف عقوبة الفاعل الأصلي","يعاقب بعقوبة الإفشاء فقط","يعفى من العقاب إذا أبلغ الهيئة"],"a":0}]},{"n":"27","chapter":"","source":"دون الاخلال بأي عقوبة أشد ورد النص عليها في اي تشريع آخر يعاقب كل من اعتدى على أحد\nالمبلغين أو الشهود أو المخبرين أو الخبراء » بسبب ما قاموا به للكشف عن الفساد أو اساء\nمعاملتهم أو ميز في التعامل بينهم أو تعسف في استعمال السلطة ضدهم أو منعهم من الادلاء\nبشهادتهم أو من الابلاغ عن الفساد بالحبس مدة لا تقل عن سنة » وفي حال استخدام القوة أو\nالتهديد بإشهار السلاح أو اي وسيلة اكراه مادية اخرى فتكون العقوبة الحبس لمدة لا تقل عن\nسنتين وبغرامة لا تزيد على عشرة الاف دينار.","notes":[],"title":"الاعتداء على المشمولين بالحماية","memo":"⭐ الاعتداء على المبلغين أو الشهود أو المخبرين أو الخبراء أو إساءة معاملتهم أو منعهم من الشهادة: حبس لا يقل عن سنة\n⭐ عند استخدام القوة أو التهديد بالسلاح أو الإكراه المادي: حبس لا يقل عن سنتين وغرامة لا تزيد على عشرة آلاف دينار","qs":[{"q":"عقوبة من منع أحد الشهود من الإدلاء بشهادته في قضية فساد دون استخدام القوة:","o":["الحبس مدة لا تقل عن سنة","الحبس مدة لا تقل عن سنتين","الحبس مدة لا تزيد على ثلاثة أشهر","الحبس مدة لا تقل عن أربعة أشهر"],"a":0},{"q":"إذا استخدم المعتدي على أحد المبلغين عن الفساد التهديد بإشهار السلاح، تكون العقوبة:","o":["الحبس مدة لا تقل عن سنتين وغرامة لا تزيد على عشرة آلاف دينار","الحبس مدة لا تقل عن سنة","الحبس مدة لا تقل عن ستة أشهر ولا تزيد على سنة","الحبس مدة لا تقل عن ثلاث سنوات وغرامة لا تزيد على خمسة آلاف دينار"],"a":0}]},{"n":"28","chapter":"","source":"أ. يعاقب كل من الشريك أو المتدخل أو المحرض في جريمة فساد بالعقوبة المقررة للفاعل.\nب. يعفى من ثلثي العقوبة كل من كان فاعلاً أو شريكاً أو متدخلاً أو محرضاً في جريمة فساد قدم للهيئة أو للسلطات المختصة معلومات أو أدلة أو بينات أدت إلى استرداد الأموال المتحصلة عن الفساد.\nج. لا تجري الملاحقة بحق المذكورين في الفقرة (ب) من هذه المادة إذا تم تقديم المعلومات قبل اكتشاف الفساد.","notes":[],"title":"الشريك والمتدخل والمحرض والإعفاء","memo":"⭐ الشريك والمتدخل والمحرض يعاقبون بعقوبة الفاعل\n⭐ يعفى من ثلثي العقوبة من قدم معلومات أو أدلة أدت إلى استرداد الأموال المتحصلة عن الفساد\n⭐ لا تجري الملاحقة إذا قدمت المعلومات قبل اكتشاف الفساد","qs":[{"q":"يعاقب المتدخل أو المحرض في جريمة فساد بـ:","o":["العقوبة المقررة للفاعل","نصف العقوبة المقررة للفاعل","ثلث العقوبة المقررة للفاعل","ثلثي العقوبة المقررة للفاعل"],"a":0},{"q":"شريك في جريمة فساد قدم للهيئة بعد اكتشاف الفساد أدلة أدت إلى استرداد الأموال المتحصلة عنه، فإنه:","o":["يعفى من ثلثي العقوبة","يعفى من العقوبة كلياً","لا تجري الملاحقة بحقه","يعفى من نصف العقوبة"],"a":0},{"q":"فاعل في جريمة فساد قدم معلومات للسلطات المختصة قبل اكتشاف الفساد أدت إلى استرداد الأموال، فإن الحكم:","o":["لا تجري الملاحقة بحقه","يعفى من ثلثي العقوبة","يعفى من نصف العقوبة","تخفض عقوبته إلى الغرامة"],"a":0}]},{"n":"29","chapter":"","source":"على الرغم مما ورد في أي تشريع آخر:\nأ. لا تسري أحكام التقادم على دعوى الحق العام والعقوبات المتعلقة بالفساد ولا تسري كذلك على استرداد الأموال المتحصلة عن الفساد.\nب. لا يحول صدور قرار عن المحكمة بإسقاط دعوى الحق العام أو بوقف الملاحقة أو الإعفاء من العقوبة لتوافر أي من حالات موانع العقاب أو لانتفاء المسؤولية دون الاستمرار في استرداد الأموال المتحصلة عن الفساد.","notes":[],"title":"عدم التقادم واسترداد الأموال","memo":"⭐ لا تسري أحكام التقادم على دعوى الحق العام والعقوبات المتعلقة بالفساد ولا على استرداد الأموال المتحصلة عنه\n⭐ إسقاط دعوى الحق العام أو وقف الملاحقة أو الإعفاء من العقوبة لا يحول دون الاستمرار في استرداد الأموال","qs":[{"q":"بالنسبة لدعوى الحق العام والعقوبات المتعلقة بالفساد واسترداد الأموال المتحصلة عنه، فإن أحكام التقادم:","o":["لا تسري عليها","تسري بعد عشر سنوات","تسري على العقوبات دون استرداد الأموال","تسري على دعوى الحق العام دون استرداد الأموال"],"a":0},{"q":"صدر قرار عن المحكمة بوقف الملاحقة بحق متهم بالفساد لتوافر مانع من موانع العقاب، فإن ذلك:","o":["لا يحول دون الاستمرار في استرداد الأموال المتحصلة عن الفساد","يوقف إجراءات استرداد الأموال","يوجب رد الأموال المحجوزة إليه","يحيل الأمر إلى مجلس الوزراء للبت في الأموال"],"a":0}]},{"n":"30","chapter":"","source":"أ. للهيئة إنشاء حساب أمانات لدى البنك المركزي أو بنك محلي يعتمده المجلس بناء على تنسيب الرئيس يسمى (حساب أمانات التسويات والمصالحات) يخصص لحفظ وإدارة الأموال والمنافع المتحصلة عن أفعال الفساد والتي تم استردادها أو الحجز عليها وإلى حين تسليمها لمستحقيها.\nب. تنظم جميع الشؤون المتعلقة بحساب الأمانات المنشأ لدى البنك المحلي المشار إليه في الفقرة (أ) من هذه المادة بمقتضى نظام يصدر لهذه الغاية.","notes":[],"title":"حساب أمانات التسويات والمصالحات","memo":"⭐ للهيئة إنشاء (حساب أمانات التسويات والمصالحات) لدى البنك المركزي أو بنك محلي يعتمده المجلس بتنسيب الرئيس\n⭐ يخصص لحفظ وإدارة الأموال المستردة أو المحجوزة إلى حين تسليمها لمستحقيها\n⭐ شؤون الحساب لدى البنك المحلي تنظم بنظام","qs":[{"q":"ينشأ (حساب أمانات التسويات والمصالحات) لدى:","o":["البنك المركزي أو بنك محلي يعتمده المجلس بناء على تنسيب الرئيس","وزارة المالية حصراً","البنك المركزي حصراً","أي بنك يختاره الأمين العام"],"a":0},{"q":"يخصص (حساب أمانات التسويات والمصالحات) لـ:","o":["حفظ وإدارة الأموال المتحصلة عن الفساد المستردة أو المحجوزة إلى حين تسليمها لمستحقيها","تمويل نفقات الهيئة التشغيلية","صرف المساعدات المالية للمبلغين والشهود","إيداع الغرامات المحكوم بها في قضايا الفساد"],"a":0}]},{"n":"31","chapter":"","source":"أ. تكون للهيئة موازنة مستقلة، وتبدأ سنتها المالية في اليوم الأول من شهر كانون الثاني من كل سنة وتنتهي في اليوم الحادي والثلاثين من شهر كانون الأول من السنة ذاتها.\nب. تتكون الموارد المالية للهيئة مما يلي:\n1. ما يرصد لها في الموازنة العامة.\n2. المساعدات والهبات والمنح وأي موارد أخرى يقرر المجلس قبولها شريطة موافقة مجلس الوزراء عليها إذا كانت من مصدر غير أردني.\nج. تخضع حسابات الهيئة لرقابة ديوان المحاسبة.","notes":[],"title":"موازنة الهيئة ومواردها","memo":"⭐ موازنة مستقلة، وسنتها المالية من 1 كانون الثاني إلى 31 كانون الأول\n⭐ الموارد: ما يرصد في الموازنة العامة، والمساعدات والهبات والمنح التي يقبلها المجلس (بموافقة مجلس الوزراء إذا كانت من مصدر غير أردني)\n⭐ تخضع حساباتها لرقابة ديوان المحاسبة","qs":[{"q":"يشترط لقبول الهبات والمنح المقدمة للهيئة إذا كانت من مصدر غير أردني:","o":["موافقة مجلس الوزراء","موافقة ديوان المحاسبة","موافقة رئيس الهيئة فقط","موافقة مجلس الأمة"],"a":0},{"q":"تخضع حسابات هيئة النزاهة ومكافحة الفساد لرقابة:","o":["ديوان المحاسبة","البنك المركزي","وزارة المالية","مجلس النواب مباشرة"],"a":0},{"q":"تبدأ السنة المالية لهيئة النزاهة ومكافحة الفساد في:","o":["اليوم الأول من شهر كانون الثاني","اليوم الأول من شهر نيسان","اليوم الأول من شهر تموز","اليوم الأول من شهر تشرين الأول"],"a":0}]},{"n":"32","chapter":"","source":"تتمتع الهيئة بالإعفاءات والتسهيلات التي تتمتع بها الوزارات والدوائر الحكومية.","notes":[],"title":"إعفاءات الهيئة وتسهيلاتها","memo":"⭐ تتمتع الهيئة بالإعفاءات والتسهيلات التي تتمتع بها الوزارات والدوائر الحكومية","qs":[{"q":"تتمتع هيئة النزاهة ومكافحة الفساد بالإعفاءات والتسهيلات التي تتمتع بها:","o":["الوزارات والدوائر الحكومية","المؤسسات العامة المستقلة فقط","الشركات المساهمة العامة","البلديات"],"a":0}]},{"n":"33","chapter":"","source":"أ. يطبق على الهيئة نظام الخدمة المدنية والنظام المالي ونظام اللوازم ونظام الأشغال ونظام الانتقال والسفر المعمول بها لدى الوزارات والدوائر الحكومية.\nب. لغايات تنفيذ أحكام الفقرة (أ) من هذه المادة، يمارس الرئيس صلاحيات الوزير المختص ويمارس الأمين العام صلاحيات الأمين العام المنصوص عليها في الأنظمة المشار إليها في تلك الفقرة.","notes":[],"title":"الأنظمة المطبقة على الهيئة","memo":"⭐ يطبق على الهيئة نظام الخدمة المدنية والنظام المالي ونظام اللوازم ونظام الأشغال ونظام الانتقال والسفر\n⭐ يمارس الرئيس صلاحيات الوزير المختص، والأمين العام صلاحيات الأمين العام في تلك الأنظمة","qs":[{"q":"لغايات تطبيق نظام الخدمة المدنية والنظام المالي على الهيئة، يمارس رئيس الهيئة صلاحيات:","o":["الوزير المختص","الأمين العام","رئيس الوزراء","مجلس الوزراء"],"a":0},{"q":"أي مما يلي ليس من الأنظمة التي نص القانون على تطبيقها على الهيئة؟","o":["نظام الهيئات المستقلة الخاص","نظام الخدمة المدنية","نظام اللوازم","نظام الانتقال والسفر"],"a":0}]},{"n":"34","chapter":"","source":"أ. يلغى كل من:\n1. قانون ديوان المظالم رقم (11) لسنة 2008.\n2. قانون هيئة مكافحة الفساد رقم (62) لسنة 2006.\nب. على أن يستمر العمل بالأنظمة والتعليمات الصادرة بمقتضاه إلى أن تلغى أو تعدل أو يستبدل غيرها بها وفقاً لأحكام هذا القانون.\nج. تعتبر الهيئة الخلف القانوني والواقعي لكل من ديوان المظالم وهيئة مكافحة الفساد وتؤول إليها جميع موجوداتهما وتنقل إليها جميع الحقوق والالتزامات المترتبة عليهما، وينقل إليها موظفو ديوان المظالم وهيئة مكافحة الفساد وتعتبر خدماتهم في الهيئة استمراراً لخدماتهم السابقة.\nد. يمارس مجلس هيئة مكافحة الفساد القائم عند نفاذ أحكام هذا القانون مهام المجلس إلى حين تشكيله وفقاً لأحكام هذا القانون ويمارس رئيس هيئة مكافحة الفساد مهام الرئيس وصلاحياته إلى حين تعيين رئيس وفقاً لأحكام هذا القانون.","notes":[],"title":"الإلغاء والخلف القانوني","memo":"⭐ ألغي قانون ديوان المظالم رقم (11) لسنة 2008 وقانون هيئة مكافحة الفساد رقم (62) لسنة 2006\n⭐ الهيئة الخلف القانوني والواقعي لديوان المظالم وهيئة مكافحة الفساد، وخدمات موظفيهما استمرار لخدماتهم السابقة\n⭐ يمارس مجلس هيئة مكافحة الفساد القائم مهام المجلس إلى حين تشكيله","qs":[{"q":"تعتبر هيئة النزاهة ومكافحة الفساد الخلف القانوني والواقعي لكل من:","o":["ديوان المظالم وهيئة مكافحة الفساد","ديوان المحاسبة وهيئة مكافحة الفساد","ديوان المظالم ودائرة إشهار الذمة المالية","ديوان الرقابة والتفتيش الإداري وديوان المظالم"],"a":0},{"q":"من القوانين التي ألغاها قانون النزاهة ومكافحة الفساد لسنة 2016:","o":["قانون هيئة مكافحة الفساد رقم (62) لسنة 2006","قانون الكسب غير المشروع","قانون الجرائم الاقتصادية","قانون ديوان المحاسبة"],"a":0},{"q":"تعتبر خدمات موظفي ديوان المظالم وهيئة مكافحة الفساد المنقولين إلى الهيئة:","o":["استمراراً لخدماتهم السابقة","خدمة جديدة تبدأ من تاريخ النقل","خدمة على حساب العقود","منتهية ويعاد تعيينهم بقرار من المجلس"],"a":0}]},{"n":"35","chapter":"","source":"يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ أحكام هذا القانون.","notes":[],"title":"أنظمة تنفيذ القانون","memo":"⭐ يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ أحكام القانون","qs":[{"q":"يصدر الأنظمة اللازمة لتنفيذ أحكام قانون النزاهة ومكافحة الفساد:","o":["مجلس الوزراء","مجلس الهيئة","رئيس الهيئة","رئيس الوزراء"],"a":0}]},{"n":"36","chapter":"","source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","notes":[],"title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام القانون","qs":[]}]};
